// === Tab: mySketch ===
let lapse = 0;    // timer

function preload(){
  sh = loadShader('https://openprocessing.org/sketch/848655/files/shader_vert.txt', 'shader_frag.txt');
}

function setup() {
  createCanvas(1112, 1112);
  g = createGraphics(width, height, WEBGL);
	(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) = width / 2;
	(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) = height /2;
}

function draw() {
  p = pixelDensity();
  sh.setUniform("smp", g);
  sh.setUniform("time", millis() / 10000.0);
  sh.setUniform("mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))*p, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))*p]);
  sh.setUniform("resolution", [width*p, height*p]);

  g.shader(sh);
  g.rect(0, 0, width, height);
  image(g, 0, 0);
}

function mousePressed(){
// prevents mouse press from registering twice
  if (frameCount - lapse > 15){
    save('pix.jpg');
    lapse = frameCount;
  }
}

